 /*
@@ -128,7 +128,9 @@

 status = smb_composite_connect_recv(ctx, state->mem_ctx);
 if (!NT_STATUS_IS_OK(status)) {
- reopen_connection(state);
+ event_add_timed(state->ev, state->mem_ctx, 
