 if (!NT_STATUS_IS_OK(status)) {
 if (NT_STATUS_EQUAL(status, NT_STATUS_END_OF_FILE)) {
- reopen_connection(state);
+ event_add_timed(state->ev, state->mem_ctx, 
+ timeval_current_ofs(1,0), 
+ reopen_connection, state);
 } else {
 DEBUG(0,("Lock failed - %s\n", nt_errstr(status)));
 lock_failed++;

